export default JSON.parse("{\"workId\":\"liezi\",\"chapter\":{\"id\":\"liezi_ch-1\",\"workId\":\"liezi\",\"order\":1,\"title\":\"天瑞\",\"difficulty\":2,\"estimatedMinutes\":30,\"passageIds\":[\"liezi_ch-1_p-1\",\"liezi_ch-1_p-2\",\"liezi_ch-1_p-3\",\"liezi_ch-1_p-4\",\"liezi_ch-1_p-5\",\"liezi_ch-1_p-6\",\"liezi_ch-1_p-7\",\"liezi_ch-1_p-8\",\"liezi_ch-1_p-9\",\"liezi_ch-1_p-10\",\"liezi_ch-1_p-11\",\"liezi_ch-1_p-12\",\"liezi_ch-1_p-13\",\"liezi_ch-1_p-14\",\"liezi_ch-1_p-15\"],\"tags\":[]},\"passages\":[{\"id\":\"liezi_ch-1_p-1\",\"chapterId\":\"liezi_ch-1\",\"order\":1,\"canonicalText\":\"子列子居鄭圃，四十年人無識者。將國先後並事之，國人皆以列子為神仙。列子居鄭圃，四十年人無識者。國君卿大夫視之，猶眾庶也。國不足，將往衛。弟子曰：「先生往無反期，弟子敢有所問；先生奚以教？先生不聞壺丘子林之言乎？」子列子曰：「壺丘子何言哉？雖然，夫子嘗語伯昏瞀人。吾側聞之，試以告女。其言曰：有生不生，有化不化。不生者能生生，不化者能化化。生者不能不生，化者不能不化，故常生常化。常生常化者，無時不生，無時不化。陰陽爾，四時爾，不生者疑獨，不化者往復。往復，其際不可終；疑獨，其道不可窮。《黃帝書》曰：『穀神不死，是謂玄牝。玄牝之門，是謂天地之根。綿綿若存，用之不勤。』故生物者不生，化物者不化。自生自化，自形自色，自智自力，自消自息。謂之生化形色智力消息者，非也。」\",\"sentenceIds\":[\"liezi_ch-1_p-1_s-1\",\"liezi_ch-1_p-1_s-2\",\"liezi_ch-1_p-1_s-3\",\"liezi_ch-1_p-1_s-4\",\"liezi_ch-1_p-1_s-5\",\"liezi_ch-1_p-1_s-6\",\"liezi_ch-1_p-1_s-7\",\"liezi_ch-1_p-1_s-8\",\"liezi_ch-1_p-1_s-9\",\"liezi_ch-1_p-1_s-10\",\"liezi_ch-1_p-1_s-11\",\"liezi_ch-1_p-1_s-12\",\"liezi_ch-1_p-1_s-13\",\"liezi_ch-1_p-1_s-14\",\"liezi_ch-1_p-1_s-15\",\"liezi_ch-1_p-1_s-16\",\"liezi_ch-1_p-1_s-17\",\"liezi_ch-1_p-1_s-18\",\"liezi_ch-1_p-1_s-19\",\"liezi_ch-1_p-1_s-20\",\"liezi_ch-1_p-1_s-21\",\"liezi_ch-1_p-1_s-22\",\"liezi_ch-1_p-1_s-23\",\"liezi_ch-1_p-1_s-24\",\"liezi_ch-1_p-1_s-25\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"列子居住在鄭國郊野的圃田，隱居長達四十年之久，世俗間沒有誰能真正識得他的深邃道行。後來鄭國國君與卿大夫視他與一般平民無異。鄭國發生饑荒糧食匱乏，列子準備前往衛國謀生。眾弟子說：先生此去不知何時才能返回，弟子大膽有所請教；先生將用什麼教誨我們呢？先生難道沒有聽聞過老師壺丘子林的微言大義嗎？列子說：壺丘子老師平時何嘗多言呢？雖然如此，老師過去曾同伯昏瞀人講論過，我當時在旁側聽到了，現在試著講給你們聽。老師的話說：有一個不被生出的本體，但能生出一切萬物；有一個不被轉化的本體，但能轉化一切萬物。被生出的萬物無法不生生不息，被轉化的萬物無法不時刻演化，所以宇宙處於永恆的常生與常化之中。這永恆的生化，無時無刻不在生發，無時無刻不在轉化。陰陽的消長是這樣，四季的更替也是這樣。那不生者超然獨立於萬物之上，那不化者在生化中周而復始往復循環。往復循環，其時空邊界永無終結；超然獨立，其深奧大道永不可窮盡。《黃帝書》（即老子引文）說：虛空的神妙生機永不寂滅，這就是孕育萬物的玄牝母體；玄牝母體的大門，正是天地萬物的終極根源。綿綿不絕若隱若存，取之不盡用之不竭。所以賦予萬物生命的本體自身不入生死，推動萬物演化的本體自身不受轉化。萬物是在大道的滋養下自然生長、自然轉化、自成形態、自具色彩、自生智謀、自運力量、自生自滅。若認為有某個具有人格意志的主宰者在強行主宰這一切生化、形色、智力與消長，那就大錯特錯了！\",\"analysis\":\"【篇旨與天瑞開篇宇宙發生與自生自化論】〈天瑞〉開宗明義——通過壺丘子林與列子傳道，系統闡述「不生者生生、不化者化化」的本體論，引用《道德經》第六章「穀神不死玄牝之門」，論證萬物「自生自化、無主宰無造作者」的自然唯物論哲學。\\\\n【詞義訓詁】「鄭圃」：鄭國圃田，列子隱居地；「有生不生」：生化萬物之本體（道）自身超越生滅；「疑獨」：疑借為擬，端凝超拔、獨立不改之貌；「自形自色」：萬物各依天性自然生長，否定有神論主宰。\\\\n【本體論高度】確立大道無形、自發演化之根本法則，為全書奠定唯物自然哲學基調。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-1_p-2\",\"chapterId\":\"liezi_ch-1\",\"order\":2,\"canonicalText\":\"子列子曰：「昔者聖人因陰陽以統天地。夫有形者生於無形，則天地安從生？故曰：有太易，有太初，有太始，有太素。太易者，未見氣也：太初者，氣之始也；太始者，形之始也；太素者，質之始也。氣形質具而未相離，故曰渾淪。渾淪者，言萬物相渾淪而未相離也。視之不見，聽之不聞，循之不得，故曰易也。易無形埒，易變而為一，一變而為七，七變而為九。九變者，窮也，乃復變而為一。一者，形變之始也。清輕者上為天，濁重者下為地，沖和氣者為人；故天地含精，萬物化生。」\",\"sentenceIds\":[\"liezi_ch-1_p-2_s-1\",\"liezi_ch-1_p-2_s-2\",\"liezi_ch-1_p-2_s-3\",\"liezi_ch-1_p-2_s-4\",\"liezi_ch-1_p-2_s-5\",\"liezi_ch-1_p-2_s-6\",\"liezi_ch-1_p-2_s-7\",\"liezi_ch-1_p-2_s-8\",\"liezi_ch-1_p-2_s-9\",\"liezi_ch-1_p-2_s-10\",\"liezi_ch-1_p-2_s-11\",\"liezi_ch-1_p-2_s-12\",\"liezi_ch-1_p-2_s-13\",\"liezi_ch-1_p-2_s-14\",\"liezi_ch-1_p-2_s-15\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"列子說：古代聖人順應陰陽二氣的規律來統攝認識天地萬物。世間一切有形質的事物皆產生於無形無相之中，那麼天地宇宙最初又是從何處誕生的呢？所以說：宇宙演化經歷了太易、太初、太始、太素四個階段。所謂太易，是連最原始的氣息都尚未出現的純虛無狀態；所謂太初，是原始元氣開始萌生的階段；所謂太始，是有形形態開始萌發的階段；所謂太素，是具體物質實質開始凝聚的階段。氣、形、質三者都已具備卻尚未彼此分離獨立，這種混沌一體的原始狀態就叫做渾淪。所謂渾淪，是指天地萬物渾然交融在一起尚未彼此分化。看它看不見形體，聽它聽不到聲音，摸它摸不到邊際，所以稱之為易。太易本體沒有任何形體邊界（無形埒），太易演化為元氣之一，一演化為陰陽水火木金土之七，七進一步演化為陽數之極之九。九是陽數演化之窮極，隨後又復歸轉化為純一。這一，就是具體事物形態演化的開端。其中清朗輕盈的陽氣上升匯聚成為蒼天，渾濁沉重的陰氣下沉凝聚成為大地，陰陽交感融通的和諧中和之氣孕育生成了人類；所以天地蘊含陰陽精華，世間萬物由此全面化育誕生。\",\"analysis\":\"【篇旨與五太宇宙演化模型太易太初太始太素渾淪】中國哲學史上最著名的宇宙生成論經典——提出「太易（虛無）→ 太初（氣之始）→ 太始（形之始）→ 太素（質之始）→ 渾淪（未分）→ 分化天地萬物」的完整演化階段論。\\\\n【詞義訓詁】「形埒」：埒，音列，邊界、輪廓界限；「渾淪」：混沌未分、全息交融之原始狀態；「一變為七，七變為九」：先秦數術哲學對宇宙分化級數之表述。\\\\n【科學哲學史價值】這是一幅極具東方思辨色彩的宇宙大爆炸與物質演化模型，從無場到能量、從粒子到凝聚態，體現了深刻的物質演化直覺。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-1_p-3\",\"chapterId\":\"liezi_ch-1\",\"order\":3,\"canonicalText\":\"子列子曰：「天地無全功，聖人無全能，萬物無全用。故天職生覆，地職形載，聖職教化，物職所宜。然則天有所短，地有所長，聖有所窮，物有所通。何則？生覆者不能形載，形載者不能教化，教化者不能違所宜，宜定者不出所位。故天地之道，非陰則陽；聖人之教，非仁則義；萬物之宜，非柔則剛：此皆隨所宜而不能出其位者也。」\",\"sentenceIds\":[\"liezi_ch-1_p-3_s-1\",\"liezi_ch-1_p-3_s-2\",\"liezi_ch-1_p-3_s-3\",\"liezi_ch-1_p-3_s-4\",\"liezi_ch-1_p-3_s-5\",\"liezi_ch-1_p-3_s-6\",\"liezi_ch-1_p-3_s-7\",\"liezi_ch-1_p-3_s-8\",\"liezi_ch-1_p-3_s-9\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"列子說：宇宙天地沒有完美無缺的全功，至高聖人沒有包辦一切的全能，世間萬物沒有無所不包的全用。所以上天的職責在於生發與覆蓋萬物，大地的職責在於賦形與承載萬物，聖人的職責在於引導教化百姓，萬物的職責在於發揮各自天然適宜的功用。既然如此，上天也有其顧及不到的短處，大地也有其無可替代的長處，聖人也有其智力窮盡的邊界，普通萬物也有其各顯神通的通達。為什麼呢？因為只負責生化覆蓋的天無法同時承載重物，負責承載的大地無法去承擔教化之責，負責教化的聖人無法違背事物客觀適宜的本性，而特性固定的物體無法超越其既定的功能範疇。所以天地的法則，不是偏陽就是偏陰；聖人的教化，不是側重於仁就是側重於義；萬物的適宜屬性，不是偏柔就是偏剛：這些都各自隨順其特定的客觀功能，而絕無法超越其自身的固有位階與局限啊。\",\"analysis\":\"【篇旨與天地無全功聖人無全能相對局限論】破除對天地、聖人與萬物的全能迷信，確立「天有所短、地有所長、聖有所窮、物有所通」的客觀唯物主義局限論與分工哲學。\\\\n【詞義訓詁】「全功／全能／全用」：絕對化、全知全能之幻想；「物職所宜」：各物依其物理屬性發揮特定功能；「不出所位」：受制於客觀條件與職能邊界。\\\\n【認識論意義】批判任何形式的個人崇拜與全能神話，倡導各司其職、揚長避短的理性協作精神。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-1_p-4\",\"chapterId\":\"liezi_ch-1\",\"order\":4,\"canonicalText\":\"故有生者，有生生者；有形者，有形形者；有聲者，有聲聲者；有色者，有色色者；有味者，有味味者。生之所生者死矣，而生生者未嘗終；形之所形者實矣，而形形者未嘗有；聲之所聲者聞矣，而聲聲者未嘗發；色之所色者彰矣，而色色者未嘗顯；味之所味者嘗矣，而味味者未嘗呈。皆道之為也。\",\"sentenceIds\":[\"liezi_ch-1_p-4_s-1\",\"liezi_ch-1_p-4_s-2\",\"liezi_ch-1_p-4_s-3\",\"liezi_ch-1_p-4_s-4\",\"liezi_ch-1_p-4_s-5\",\"liezi_ch-1_p-4_s-6\",\"liezi_ch-1_p-4_s-7\",\"liezi_ch-1_p-4_s-8\",\"liezi_ch-1_p-4_s-9\",\"liezi_ch-1_p-4_s-10\",\"liezi_ch-1_p-4_s-11\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"所以世間有產生出來的具體生命，就必定有產生這些生命的那種能生之源；有各種具體的形體，就必定有塑造這些形體的賦形之本；有各種具體的聲音，就必定有發出這些聲音的發聲之原；有各種具體的顏色，就必定有顯現這些顏色的顯色之基；有各種具體的味道，就必定有呈現這些味道的呈味之根。那些被產生的具體生命最終都會死亡，但那個能產生生命的本源卻從未終結過；那些被塑造出來的形體都是真實可見的，但那個賦予萬物形體的本原卻從未以具體的形體存在過；那些被發出的聲音都能被人聽見，但那個產生聲音的本原卻從未發出過具體的聲響；那些被顯現的顏色都是鮮明彰顯的，但那個顯現顏色的本原卻從未顯露出具體的色彩；那些被呈現的味道都可以被品嚐到，但那個呈現味道的本原卻從未表現出具體的滋味。這一切，都是道的作用啊。\",\"analysis\":\"【訓詁與名物】：「生生者」前一個「生」是動詞，指產生、化生；後一個「生」是名詞，指生命。生生者，即產生生命（萬物）的本源，下文的形形者、聲聲者等結構相同。「終」終結。「實矣」指有實質的形體。「彰」鮮明、明顯。「呈」顯露、表現。「為」作用、作為。\\\\n\\\\n【章法與結構】：本段採用了極其嚴密的排比和對比句式。前半部分用五個排比句（有……者，有……者）提出了「現象（生、形、聲、色、味）」與「本體（生生、形形、聲聲、色色、味味）」的二元對應；後半部分又用五個對偶句，將現象的「生滅、有形、可知」與本體的「永恆、無形、不可感知」進行了強烈的對比。最後以「皆道之為也」一語破的，收束全段。\\\\n\\\\n【思想與義理】：這是《列子》對道家「本體論」的深刻闡述。文章區分了現象界的「萬物」與本體界的「道」。萬物（生、形、聲、色、味）是生滅無常、有限且可以被感官感知的；而「道」（生生者、形形者等）則是永恆不滅、無限且超越感官經驗的（未嘗終、未嘗有、未嘗發）。「道」本身雖然不具備任何具體的形態和屬性（無形、無聲），但它卻是萬物得以存在、具備各種形態與屬性的終極原因。這深刻體現了道家「無能生有」、「無用之用」的玄妙哲理，指出了感官經驗的局限性與追求形而上之「道」的必要性。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-1_p-5\",\"chapterId\":\"liezi_ch-1\",\"order\":5,\"canonicalText\":\"林類年且百歲，底春被裘，拾遺穗於故畦，並歌並行。孔子適衛，望之於野。顧謂弟子曰：「彼叟可與言者，試往訊之。」子貢請行。逆之壟端，面之而歎曰：「先生曾不悔乎，而翡歌拾穗？」林類行不返，歌不輟。子貢遂躡而詰之。林類仰而應曰：「吾何悔邪？」子貢曰：「先生少不勤行，長不競時，老無妻子，死期將至，亦有何樂而拾穗歌乎？」林類笑曰：「吾之所以為樂，人皆有之，而反以為憂。少不勤行，長不競時，故能遂算至今。老無妻子，死期將至，故能歡樂。孔子聞之，曰：「吾知其可與言，果然；然特得其一，未得其二者也。」\",\"sentenceIds\":[\"liezi_ch-1_p-5_s-1\",\"liezi_ch-1_p-5_s-2\",\"liezi_ch-1_p-5_s-3\",\"liezi_ch-1_p-5_s-4\",\"liezi_ch-1_p-5_s-5\",\"liezi_ch-1_p-5_s-6\",\"liezi_ch-1_p-5_s-7\",\"liezi_ch-1_p-5_s-8\",\"liezi_ch-1_p-5_s-9\",\"liezi_ch-1_p-5_s-10\",\"liezi_ch-1_p-5_s-11\",\"liezi_ch-1_p-5_s-12\",\"liezi_ch-1_p-5_s-13\",\"liezi_ch-1_p-5_s-14\",\"liezi_ch-1_p-5_s-15\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"林類年紀將近一百歲了，暮春時節還穿著粗皮裘，在收割過的舊田壟上撿拾遺落的稻穗，一邊走一邊歡快地歌唱。孔子前往衛國，在田野間遠遠看見了他，回頭對弟子們說：那位老者是一位值得同他交談的高士，試著前去探問他一番。子貢請求前往。子貢迎著走到田埂盡頭，面對老者嘆息道：先生難道對自己的一生就沒有絲毫後悔遺憾嗎，竟然一邊歡快歌唱一邊撿拾稻穗？林類腳步不停，歌聲不斷。子貢於是緊跟上去追問。林類仰起頭回答說：我能有什麼後悔遺憾的呢？子貢說：先生年輕時沒有勤奮立身建功，壯年時沒有同時代去競爭功名，晚年無妻無子孤苦伶仃，死期又即將降臨，究竟有什麼值得高興而能一邊撿麥穗一邊唱歌的呢？林類笑著說：我之所以能如此快樂的原因，全天下人其實都具備，只是世人反而將它們當作憂愁罷了！年輕時不盲目勞形奔波，壯年時不捲入名利競爭，所以我才能安享天年長壽至今；晚年沒有妻兒拖累，死亡的大限又即將解脫歸宿，所以我才能如此無牽無掛歡快歌唱啊！孔子聽聞子貢的匯報後說：我料定他是個可以同他論道的高人，果然不出所料；但他只領悟了道家通達生死、順應解脫的第一層境界，尚未領悟儒家入世盡責、死而後已的第二層境界啊。\",\"analysis\":\"【篇旨與林類拾穗安貧樂道通達生死】記載百歲老者林類拾穗而歌的豁達人生，通過子貢以世俗世俗成功學（勤行、競時、妻子、長壽）發問與林類的超然答辯，對比儒道生死價值觀。\\\\n【詞義訓詁】「底春」：暮春、春末；「遂算」：算，壽數，保全天賦壽命；「特得其一未得其二」：孔子評語展現儒道互補的哲學對話。\\\\n【生命啟示】破除世俗功利標準對人生的單一評判，展現個體在貧困與暮年依然能擁抱生命的純粹自由。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-1_p-6\",\"chapterId\":\"liezi_ch-1\",\"order\":6,\"canonicalText\":\"子貢倦於學，告仲尼曰：「願有所息。」仲尼曰：「生無所息。」子貢曰：「然則賜息無所乎？」仲尼曰：「有焉耳。望其壙，睪如也，填如也，鬲如也，枯如也，則知所息矣。」子貢曰：「大哉死乎！君子息焉，小人伏焉。」仲尼曰：「賜！汝知之矣。人胥知生之樂，未知生之苦；知老之憊，未知老之佚；知死之惡，未知死之息也。」\",\"sentenceIds\":[\"liezi_ch-1_p-6_s-1\",\"liezi_ch-1_p-6_s-2\",\"liezi_ch-1_p-6_s-3\",\"liezi_ch-1_p-6_s-4\",\"liezi_ch-1_p-6_s-5\",\"liezi_ch-1_p-6_s-6\",\"liezi_ch-1_p-6_s-7\",\"liezi_ch-1_p-6_s-8\",\"liezi_ch-1_p-6_s-9\",\"liezi_ch-1_p-6_s-10\",\"liezi_ch-1_p-6_s-11\",\"liezi_ch-1_p-6_s-12\",\"liezi_ch-1_p-6_s-13\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"子貢對長期的求學苦修感到身心疲憊，向孔子訴說道：我希望能有一段時間得到徹底的休息。孔子說：生命只要活著，就沒有任何可以徹底停歇休息的時候。子貢問：難道我端木賜就永遠沒有可以安息的地方了嗎？孔子說：當然有安息之所啊！你看那墳墓，高高隆起宛如丘陵，厚實填築堅固安詳，棺槨嚴密封閉隔絕塵囂，形骸枯寂萬緣放下，那時你就知道真正的安息之處了！子貢感嘆道：死亡真是偉大啊！有德君子在那裡得到了徹底的安息，奸邪小人在那裡受到了永恆的伏法收斂！孔子說：賜啊！你現在終於真正理解了！世人都只懂得活著的歡樂，卻不懂得活著所承受的無盡苦痛；只懂得衰老的疲憊，卻不懂得衰老所帶來的清閒安逸；只懂得死亡的可怕可厭，卻不懂得死亡乃是生命漫長勞碌之後最神聖慈悲的徹底安息啊！\",\"analysis\":\"【篇旨與生無所息大哉死乎生死安息論】先秦生死哲學最深刻璀璨之名篇——孔子與子貢論「生無所息」與「死為大息」，破除對死亡的恐懼厭惡，將死亡昇華為生命勞碌後的莊嚴安息。\\\\n【詞義訓詁】「生無所息」：只要生命存在就需承擔道德與實踐責任；「睪如填如鬲如枯如」：形容墓穴棺槨安詳深沉之象；「小人伏焉」：小人在死亡面前亦不得不收斂惡念。\\\\n【生死尊嚴】賦予死亡以神聖的解脫與平等意義，引導人們在生時盡心負責、在死時安詳接納。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-1_p-7\",\"chapterId\":\"liezi_ch-1\",\"order\":7,\"canonicalText\":\"晏子曰：「善哉，古之有死也！仁者息焉，不仁者伏焉。」死也者，德之徼也。古者謂死人為「歸人」，夫言死人為「歸人」，則生人為「行人」矣。行而不知歸，失家者也。一人失家，一世非之；天下失家，莫知非也。有人去鄉土、離六親、廢家業、遊於四方而不歸者，何人哉？世必謂之狂蕩之人矣。又有人鍾規矩、備節制、謀官祿、爭功名、終身馳騖而不返者，何人哉？世必謂之智謀之士矣。此二者，皆失家也，而世或笑之，或貴之，未知其俱惑也。\",\"sentenceIds\":[\"liezi_ch-1_p-7_s-1\",\"liezi_ch-1_p-7_s-2\",\"liezi_ch-1_p-7_s-3\",\"liezi_ch-1_p-7_s-4\",\"liezi_ch-1_p-7_s-5\",\"liezi_ch-1_p-7_s-6\",\"liezi_ch-1_p-7_s-7\",\"liezi_ch-1_p-7_s-8\",\"liezi_ch-1_p-7_s-9\",\"liezi_ch-1_p-7_s-10\",\"liezi_ch-1_p-7_s-11\",\"liezi_ch-1_p-7_s-12\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"晏子說：多麼美好啊，自古以來生命都設有死亡這一終點！仁者在死亡中獲得安息，不仁者在死亡前低下頭顱伏罪。死亡這件事，正是天道對世間道德公正的最終審查界限（德之徼）。古代人把死去的人稱作歸人（回歸家園的人），既然把死者稱作回歸之人，那麼活著的人自然就是行路旅人了。一個人在外趕路卻不知道回歸家園，這就是迷失了家園的流浪者。若是一個人迷失了家園，舉世都會責備他迷茫；但全天下人都迷失了生命的歸宿家園，世人卻沒有誰懂得去反省責備了！如果有一個人背棄故土家鄉、離開父母至親、荒廢家族祖業、常年遊蕩在四方而不肯回歸，這是個什麼樣的人呢？世人必定會一致斥責他為狂妄放蕩的浪子！但又有另一種人，死板執著於世俗規矩，處處受制於繁瑣禮制，窮盡心機謀求高官厚祿，不擇手段爭奪名利地位，一輩子在名利場中瘋狂奔波馳騁而不知回頭，這又是個什麼樣的人呢？世俗大眾卻必定會對他推崇備至、稱讚他是大有智謀的能人！這兩種人，本質上其實全都迷失了自己真正的生命家園啊！然而世俗之人有的嘲笑前者，有的尊崇後者，卻完全不知道這兩者在迷失生命本真這一點上其實同樣愚昧困惑啊！\",\"analysis\":\"【篇旨與生人為行人生死為歸人名利迷途批判】以「死者為歸人、生人為行人」為精妙隱喻，痛批世人執著於官祿功名、終身馳騖不返之「失家」悲劇，揭示名利客與浪蕩子同屬迷失本真。\\\\n【詞義訓詁】「德之徼」：徼，音叫，邊界、巡查界限；死亡是天道對道德功過的終極結算；「失家」：迷失精神家園與本真生命。\\\\n【精神反思】深刻抨擊世俗功利主義將名利狂熱美化為「智謀」，呼喚現代人停下盲目內耗、回歸精神家園。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-1_p-8\",\"chapterId\":\"liezi_ch-1\",\"order\":8,\"canonicalText\":\"杞國有人憂天地崩墜，身亡所寄，廢寢食者。又有憂彼之所憂者，因往曉之，曰：「天，積氣耳，亡處亡氣。若屈伸呼吸，終日在天中行止，奈何憂崩墜乎？」其人曰：「天果積氣，日月星宿，不當墜耶？」曉之者曰：「日月星宿，亦積氣中之有光耀者，只使墜，亦不能有所中傷。」其人曰：「奈地壞何？」曉之者曰：「地，積塊耳，充塞四虛，亡處亡塊。若躇步跐蹈，終日在地上行止，奈何憂其壞？」其人舍然大喜，曉之者亦舍然大喜。長廬子聞而笑之曰：「虹蜺也，雲霧也，風雨也，四時也，此積氣之成乎天者也。山嶽也，河海也，金石也，火木也，此積形之成乎地者也。知積氣也，知積塊也，奚謂不壞？夫天地，空中之一細物，有中之最巨者。難終難窮，此固然矣；難測難識，此固然矣。憂其壞者，誠為大遠；言其不壞者，亦未為是也。天地不得不壞，則會壞。遇其壞時，奚為不憂哉？」子列子聞而笑曰：「言天地壞者亦謬，言天地不壞者亦謬。壞與不壞，吾所不能知也。雖然，彼一也，此一也。故生不知死，死不知生；來不知往，往不知來。壞與不壞，吾何容心哉？」\",\"sentenceIds\":[\"liezi_ch-1_p-8_s-1\",\"liezi_ch-1_p-8_s-2\",\"liezi_ch-1_p-8_s-3\",\"liezi_ch-1_p-8_s-4\",\"liezi_ch-1_p-8_s-5\",\"liezi_ch-1_p-8_s-6\",\"liezi_ch-1_p-8_s-7\",\"liezi_ch-1_p-8_s-8\",\"liezi_ch-1_p-8_s-9\",\"liezi_ch-1_p-8_s-10\",\"liezi_ch-1_p-8_s-11\",\"liezi_ch-1_p-8_s-12\",\"liezi_ch-1_p-8_s-13\",\"liezi_ch-1_p-8_s-14\",\"liezi_ch-1_p-8_s-15\",\"liezi_ch-1_p-8_s-16\",\"liezi_ch-1_p-8_s-17\",\"liezi_ch-1_p-8_s-18\",\"liezi_ch-1_p-8_s-19\",\"liezi_ch-1_p-8_s-20\",\"liezi_ch-1_p-8_s-21\",\"liezi_ch-1_p-8_s-22\",\"liezi_ch-1_p-8_s-23\",\"liezi_ch-1_p-8_s-24\",\"liezi_ch-1_p-8_s-25\",\"liezi_ch-1_p-8_s-26\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"杞國有一個人整天擔憂蒼天崩塌、大地陷落，自己將死無所寄身，以致於焦慮到廢寢忘食。又有一個熱心人擔憂他的焦慮，於是特地前去開導啟發他，說：蒼天不過是積聚的氣體罷了，世間無處不存在大氣。你每天肢體屈伸、呼吸吐納，整天都在這大氣層中行動起居，為什麼還要擔憂蒼天崩塌呢？那人問：如果蒼天果然只是積聚的氣體，那日月星辰難道不會掉落下來嗎？開導者說：日月星辰，也不過是大氣層中能夠發出光芒的氣體凝結物罷了，縱然真的掉落下來，也絕不可能把人砸傷擊傷。那人又問：那如果大地陷落崩壞了該怎麼辦呢？開導者說：大地不過是堆積的泥土石塊罷了，充塞在四方空間之中，無處不是厚實的土塊。你每天踏步跳躍行走，整天都在這厚重大地上行動起居，為什麼還要擔憂大地崩壞陷落呢？那人聽後豁然開朗欣喜若狂，開導者也如釋重負欣喜萬分。長廬子聽聞這件事後笑著說：彩虹也罷，雲霧也罷，風雨也罷，四季也罷，這些都是氣體在大氣天空中凝聚而成的；山嶽也罷，江河也罷，金石也罷，火木也罷，這些都是形體在地面上凝聚而成的。既然知道天是積氣、地是積塊，又憑什麼斷言它們永遠不會崩壞呢？天地宇宙，不過是浩瀚虛空中懸浮的一粒細微塵埃罷了，只是在所有有形物質中算最為龐大而已。天地難以終結窮盡，這固然是事實；難以測量認識，這固然也是事實。但盲目擔憂天地崩壞，確實想得太過遙遠脫離現實；斷言天地永遠不壞，也並非完全符合真理。天地該崩壞時終究不得不壞，到了它真正崩壞毀滅的那一天，能不令人擔憂嗎？列子聽聞這兩種言論後笑著說：斷言天地必然會毀滅崩壞的說法是偏頗荒謬的，斷言天地永遠不會崩壞的說法同樣是偏頗荒謬的。天地最終究竟會不會崩壞，原本就超越了人類有限經驗所能確知預測的範圍。雖然如此，生存是一回事，死亡是另一回事；生時無法預知死後的感受，死後也無從體會生時的知覺；未來無法預知過往，過往也無法預知未來。宇宙崩壞也好、不崩壞也罷，我又何必在有限的當下為此苦苦掛懷焦慮呢！\",\"analysis\":\"【篇旨與杞人憂天千古寓言三層認識論解析】中國歷史上最著名的焦慮心理學與宇宙演化寓言——通過杞人（極度焦慮）、開導者（樸素氣論安撫）、長廬子（宏觀宇宙物質生滅論）與列子（當下超越論）四層對話，將心理學安撫深化為深邃的不可知論與存在主義當下哲學。\\\\n【詞義訓詁】「舍然」：舍通釋，釋然開朗；「空中一細物」：驚人的宇宙微塵觀，將地球視為宇宙浩瀚虛空中之一微塵；「吾何容心哉」：不為超越人類掌控之遙遠未來徒增焦慮。\\\\n【現代心理學與天體物理學】兼具現代焦慮症心理疏導與宇宙大尺度演化視角，教導人類既要具備科學敬畏，又要專注於把握當下真實生活。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-1_p-9\",\"chapterId\":\"liezi_ch-1\",\"order\":9,\"canonicalText\":\"舜問乎烝曰：「道可得而有乎？」曰：「汝身非汝有也，汝何得有夫道？」舜曰：「吾身非吾有也，孰有之哉？」曰：「是天地之委形也；生非汝有，是天地之委和也；性命非汝有，是天地之委順也；孫子非汝有，是天地之委蛻也。故行不知所往，處不知所持，食不知所味。天地之強陽氣也，又胡可得而有邪？」\",\"sentenceIds\":[\"liezi_ch-1_p-9_s-1\",\"liezi_ch-1_p-9_s-2\",\"liezi_ch-1_p-9_s-3\",\"liezi_ch-1_p-9_s-4\",\"liezi_ch-1_p-9_s-5\",\"liezi_ch-1_p-9_s-6\",\"liezi_ch-1_p-9_s-7\",\"liezi_ch-1_p-9_s-8\",\"liezi_ch-1_p-9_s-9\",\"liezi_ch-1_p-9_s-10\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"舜帝向智者烝請教道：大道可以通過求索而佔為自己私有嗎？烝回答說：你自己的身軀形體尚且都不是你所私有的，你又憑什麼想把大道佔為己有呢？舜驚訝地問：我的身體如果不是我自己私有的，那究竟是誰擁有的呢？烝回答說：這具身軀不過是天地自然暫時寄託給予你的形體罷了（委形）；你的生命活力並非你所私有，那是天地自然暫時寄託給予你的中和之氣（委和）；你的天賦性命並非你所私有，那是天地自然暫時寄託給予你的順化秩序（委順）；你的子孫後代並非你所私有，那是天地自然借你之身如同蟬蛻般代謝繁衍的新生之軀（委蛻）。所以得道聖人行走時不刻意執著於目的地，居處時不刻意死守特定位置，進食時不刻意挑剔美味口欲。萬物不過是天地間剛健運動的陽氣造化罷了，大道又怎麼可能被某個人自私占為私有呢！\",\"analysis\":\"【篇旨與身非己有天地之委委形委和委順委蛻】徹底打破個體中心主義與產權自私幻覺，提出身體、生命、性命、子孫皆為天地「委託（委形、委和、委順、委蛻）」的宇宙託管哲學。\\\\n【詞義訓詁】「委」：寄託、託付、賦予；「委蛻」：如蟬蛻皮繁衍，子孫乃天地生機之代際代謝；「強陽氣」：天地剛健生生不息之運化力量。\\\\n【存在主義解構】人並非萬物的主宰，亦非自身的終極私產所有者，而是天地造化的過客與託管者，由此獲得徹底的放下與超然。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-1_p-10\",\"chapterId\":\"liezi_ch-1\",\"order\":10,\"canonicalText\":\"齊之國氏大富，宋之向氏大貧。向氏之齊，請其術。國氏告之曰：「吾善為盜。始吾為盜也，一年而給，二年而足，三年大穰。自此以往，施及州閭。」向氏大喜，徒聞其言，不達其理。乃逾垣鑿室，手妄掇，目妄指，無所不取。未及時，以贓獲罪，沒其先居之產。向氏以為國氏之詒己也，往而怨之。國氏曰：「若為盜若何？」向氏言其狀。國氏曰：「嘻！若失為盜之道至此乎？請更語若：吾聞天有時，地有利。吾盜天地之時利，雲雨之滂沛，山澤之產育，以生吾禾，殖吾稼，築吾垣，建吾舍。陸盜禽獸，水盜魚鱉，亡非盜也。夫禾稼、土木、禽獸、魚鱉，皆天之所生，豈吾之所有？然吾盜天而亡殃。若盜人之金玉珠帛，穀粟貨財，獲罪於人，非天也。若不知天地之公，而奪人之私，何怨於吾？」\",\"sentenceIds\":[\"liezi_ch-1_p-10_s-1\",\"liezi_ch-1_p-10_s-2\",\"liezi_ch-1_p-10_s-3\",\"liezi_ch-1_p-10_s-4\",\"liezi_ch-1_p-10_s-5\",\"liezi_ch-1_p-10_s-6\",\"liezi_ch-1_p-10_s-7\",\"liezi_ch-1_p-10_s-8\",\"liezi_ch-1_p-10_s-9\",\"liezi_ch-1_p-10_s-10\",\"liezi_ch-1_p-10_s-11\",\"liezi_ch-1_p-10_s-12\",\"liezi_ch-1_p-10_s-13\",\"liezi_ch-1_p-10_s-14\",\"liezi_ch-1_p-10_s-15\",\"liezi_ch-1_p-10_s-16\",\"liezi_ch-1_p-10_s-17\",\"liezi_ch-1_p-10_s-18\",\"liezi_ch-1_p-10_s-19\",\"liezi_ch-1_p-10_s-20\",\"liezi_ch-1_p-10_s-21\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"齊國的國氏非常富有，宋國的向氏非常貧困。向氏特地前往齊國，向國氏請教致富的法術訣竅。國氏告訴他說：我最擅長的就是做大盜（善為盜）。當初我剛開始做大盜的時候，一年就物資自給自足，兩年就家境充裕，三年就大獲豐收大富大貴，從那以後積累的財富甚至能周濟施捨整個鄉里州郡。向氏聽了大喜過望，但他只聽到了字面言語，卻完全沒有理解其中的真實道理。回到宋國後，他立刻去翻越鄰居家圍牆、破壞他人房屋門窗，手胡亂抓取，眼睛看中什麼就搶什麼，沒有任何財物不去偷盜。結果沒過多久，就被官府人贓並獲依法判罪，連同他祖上遺留下來的祖產房屋也全部被官府抄沒充公。向氏認為是國氏故意欺騙坑害了自己，憤怒地跑去齊國埋怨責怪國氏。國氏問道：你究竟是怎樣去做大盜的呢？向氏把自己的所作所為如實講了一遍。國氏聽後長嘆一聲說：唉！你對做大盜之道的理解竟然荒謬落後到了這種地步嗎？請讓我再明確告訴你吧：我聽說上天有農耕時令，大地有豐饒地理資源。我所盜取的，是天地大自然的時節與地利，利用甘霖雲雨的滂沛滋潤，利用名山大澤的物產孕育，以此來種植我的莊稼穀物，繁殖我的畜牧桑麻，築造我的莊園圍牆，興建我的房屋居所。在陸地上獲取禽獸，在江河中捕撈魚鱉，這些全都是向大自然獲取的！那穀物稼穡、泥土木料、飛禽走獸、遊魚水產，全都是大自然天地的造化產物，哪裡原本是我個人所私有的呢？然而我從大自然中辛勤汲取資源卻從不遭受天災橫禍。而你卻去盜竊掠奪他人辛勤勞動積累的金銀珠寶、糧食穀粟與財富資產，你這是在人事上觸犯了國法民怨獲罪於人，絕不是大自然懲罰你啊！你根本不懂得天地資源屬於全人類大公無私的道理，反而去瘋狂搶奪他人的私人產權，你又有什麼理由來怨恨我呢！\",\"analysis\":\"【篇旨與向氏盜天大盜天地時利產權寓言】先秦經濟哲學極其幽默深刻之寓言——借「善為盜」重新定義生產勞動與財富本質：從大自然中獲取資源（盜天地時利）是正當合法的生產創造，侵犯他人勞動果實（奪人之私）是犯罪自毀。\\\\n【詞義訓詁】「善為盜」：非違法盜竊，乃指人類順應天時地利從大自然中獲取生活資料之生產活動；「奪人之私」：侵犯私人合法財產權；「大穰」：穰，音瓤，農業大豐收。\\\\n【產權與勞動價值論】精闢區分了「開發自然資源的合法勞動生產」與「侵犯他人合法產權的非法掠奪」，奠定了古典正義經濟學的產權底線。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-1_p-11\",\"chapterId\":\"liezi_ch-1\",\"order\":11,\"canonicalText\":\"燕丹子曰：「田光先生，燕國之勇士也，智深而勇沈，可與謀大事。」太子丹私見田光，曰：「燕、秦不兩立，願先生留意。」田光曰：「臣聞騏驥盛壯之時，一日千里；至其衰老，駑馬先之。今太子聞光盛壯之時，不知臣精已消亡矣。雖然，光不敢以乏國事也。所善荊軻，可使也。」太子曰：「願因先生得交於荊軻。」田光曰：「敬諾。」退而見荊軻，語之曰：「光與子相善，燕國莫不知。今太子聞光盛壯之時，不知吾形已不逮也。幸而語曰：『燕、秦不兩立，願先生留意。』光竊不自外，言足下於太子，願足下過太子於宮。」荊軻曰：「謹奉教。」田光曰：「吾聞長者之行，不使人疑之。今太子告光曰：『所言者，國之大事，願先生勿泄。』是太子疑光也。夫為行而使人疑之，非節俠也。」遂自殺以厲荊軻。\",\"sentenceIds\":[\"liezi_ch-1_p-11_s-1\",\"liezi_ch-1_p-11_s-2\",\"liezi_ch-1_p-11_s-3\",\"liezi_ch-1_p-11_s-4\",\"liezi_ch-1_p-11_s-5\",\"liezi_ch-1_p-11_s-6\",\"liezi_ch-1_p-11_s-7\",\"liezi_ch-1_p-11_s-8\",\"liezi_ch-1_p-11_s-9\",\"liezi_ch-1_p-11_s-10\",\"liezi_ch-1_p-11_s-11\",\"liezi_ch-1_p-11_s-12\",\"liezi_ch-1_p-11_s-13\",\"liezi_ch-1_p-11_s-14\",\"liezi_ch-1_p-11_s-15\",\"liezi_ch-1_p-11_s-16\",\"liezi_ch-1_p-11_s-17\",\"liezi_ch-1_p-11_s-18\",\"liezi_ch-1_p-11_s-19\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"燕太子丹對人說：田光先生是燕國頂尖的勇士，智謀深邃而勇氣沉毅，可以同他共謀國家大事。太子丹私下接見田光，懇切地說：燕國與強秦勢不兩立水火不容，希望先生能為燕國存亡多加費心。田光說：我聽說千里馬在年輕盛壯之時，能夠日行千里；等到它年老衰朽之後，連劣馬都能跑在它的前面。如今太子聽聞的是我田光年輕盛壯之時的名聲，卻不知道如今我的精氣神早已衰竭消磨殆盡了。雖然如此，我田光絕不敢因為自己年老而荒廢耽誤了國家大事。我的生死至交荊軻，是可以擔當重任託付大事的人。太子說：希望能通過先生的引薦得以同荊軻結交。田光說：遵命。田光退下後前去會見荊軻，對他說：我與先生情同手足交情深厚，燕國沒有誰不知道。如今太子聽聞的是我盛壯時的名聲，不知道我的體力精力早已無法支撐了。太子榮幸地對我說：燕秦勢不兩立，希望先生留意。我私下不拿自己當外人，向太子極力推薦了閣下，希望閣下能屈駕前往宮中拜訪太子。荊軻說：謹遵先生教誨。田光接著說：我聽聞德高望重之長者的品行，行事絕不給他人留下絲毫猜疑的空間。今天太子臨別時特意告誡我說：我們所商談的，是關係國家存亡的最高機密，希望先生千萬不要洩漏。這說明太子內心深處對我的守口如瓶產生了疑慮。凡立身行事卻引來他人猜忌懷疑，這絕不是合格的節義俠士所能容忍的！說罷，田光當場拔劍自刎以死明志，以此激勵荊軻義無反顧奔赴國難！\",\"analysis\":\"【篇旨與田光自殺礪荊軻古代燕趙死士節俠風骨】記錄戰國末期燕太子丹密謀刺秦與田光拔劍自刎以礪荊軻之悲壯史實，展現先秦「士為知己者死、重諾輕生」的極致俠義節操。\\\\n【詞義訓詁】「智深勇沈」：深謀遠慮、沉毅內斂；「非節俠也」：行事留疑有損俠士名節；「自殺以厲荊軻」：以生命為代價守護絕對機密並向荊軻展示必死之決心。\\\\n【歷史批判與反思】深刻體現燕趙戰國死士視死如歸的崇高人格，同時也折射出個人英雄主義刺殺無法阻擋歷史大一統客觀車輪的悲劇宿命。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-1_p-12\",\"chapterId\":\"liezi_ch-1\",\"order\":12,\"canonicalText\":\"孔子兼三才之道，六藝之業，弟子三千，身通六藝者七十有二人。遊於宋，匡人圍之數匝，歌鼓琴聲不絕。子路入見，曰：「何夫子之娛也？」孔子曰：「由，來！吾語汝。吾諱窮久矣，而不免，命也；求通久矣，而不得，時也。當文王既沒，文不在茲乎？天之將喪斯文也，後死者不得與於斯文也；天之未喪斯文也，匡人其如予何？夫水行不避蛟龍者，漁父之勇也；陸行不避兕虎者，獵夫之勇也；白刃交於前，視死若生者，烈士之勇也；知窮之有命，知通之有時，臨大難而不懼者，聖人之勇也。由，處矣！吾命有所制矣。」\",\"sentenceIds\":[\"liezi_ch-1_p-12_s-1\",\"liezi_ch-1_p-12_s-2\",\"liezi_ch-1_p-12_s-3\",\"liezi_ch-1_p-12_s-4\",\"liezi_ch-1_p-12_s-5\",\"liezi_ch-1_p-12_s-6\",\"liezi_ch-1_p-12_s-7\",\"liezi_ch-1_p-12_s-8\",\"liezi_ch-1_p-12_s-9\",\"liezi_ch-1_p-12_s-10\",\"liezi_ch-1_p-12_s-11\",\"liezi_ch-1_p-12_s-12\",\"liezi_ch-1_p-12_s-13\",\"liezi_ch-1_p-12_s-14\",\"liezi_ch-1_p-12_s-15\",\"liezi_ch-1_p-12_s-16\",\"liezi_ch-1_p-12_s-17\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"孔子融通天地人三才大道，精通禮樂射御書數六藝學業，門下弟子多達三千人，親身精通六藝的傑出弟子有七十二人。孔子一行遊歷周遊到宋國與衛國之間的匡地，匡地的軍民誤認孔子為陽虎，將他們重重包圍了數層之密，然而孔子在包圍圈中依然彈琴唱歌講學之聲不絕於耳。子路衝進來面見孔子，問道：先生在這種生死危難關頭，怎麼還有心情彈琴作樂呢？孔子說：仲由，過來！我告訴你。我竭力迴避窮困困厄已經很久了，然而終究無法免除困厄，這是客觀命運使然；我積極謀求行道通達已經很久了，然而終究未能如願，這是時代時機未到。當年周文王去世之後，周代的文明道統難道不就寄託在我的身上嗎？如果上天真要徹底滅絕這份神聖文明道統，那麼我這個後死之人就絕不可能掌握理解這份道統；如果上天並不想滅絕這份文明道統，匡地的區區軍民又能把我怎麼樣呢！在江河水上航行不畏避蛟龍水怪的，是漁夫的勇氣；在山林陸地行進不畏避犀牛猛虎的，是獵人的勇氣；刀光劍影利刃交鋒於眼前而將死亡看作同生存一樣平常的，是熱血烈士的勇氣；而深刻洞曉窮困困厄自有其客觀天命、深刻通曉功業通達自有其歷史時機，面臨滔天大難而內心毫無驚惶恐懼的，這才是至高無上的聖人之勇！仲由，安靜下來吧！我的生命命運早已由天地大道所主宰註定了！\",\"analysis\":\"【篇旨與匡人之圍聖人之勇知命通時文化擔當】記載孔子在匡地蒙難被圍困之際泰然絃歌不輟之典故，系統劃分「漁父之勇、獵夫之勇、烈士之勇、聖人之勇」四層勇氣階梯，展現崇高的文化使命感。\\\\n【詞義訓詁】「文不在茲乎」：茲，指孔子自身；承擔傳承華夏文明道統之自覺；「天之未喪斯文」：斯文，儒家禮樂文明；「聖人之勇」：建立在深刻洞曉歷史規律與天命自覺基礎上的終極精神定力。\\\\n【精神境界】真正的無畏源於對歷史文明使命的崇高信仰，超越匹夫之勇而具備撼人心魄的精神力量。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-1_p-13\",\"chapterId\":\"liezi_ch-1\",\"order\":13,\"canonicalText\":\"衛人有客於齊者，齊人有問之曰：「衛之君臣何如？」客曰：「君明臣忠。」齊人曰：「何以知之？」客曰：「其君好儒，禮賢下士；其臣盡節，死難不避。故知其明且忠也。」齊人曰：「然則衛何以弱？」客曰：「國小地狹，四面受敵。雖有明君忠臣，力不足以抗大國，故弱也。夫勢者，非德之所能制也。」\",\"sentenceIds\":[\"liezi_ch-1_p-13_s-1\",\"liezi_ch-1_p-13_s-2\",\"liezi_ch-1_p-13_s-3\",\"liezi_ch-1_p-13_s-4\",\"liezi_ch-1_p-13_s-5\",\"liezi_ch-1_p-13_s-6\",\"liezi_ch-1_p-13_s-7\",\"liezi_ch-1_p-13_s-8\",\"liezi_ch-1_p-13_s-9\",\"liezi_ch-1_p-13_s-10\",\"liezi_ch-1_p-13_s-11\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"衛國有一個寄居在齊國的士人客商，齊國有人向他打聽詢問道：衛國的國君與大臣治理得怎麼樣呢？客商回答說：衛國國君英明睿智，大臣忠心耿耿。齊國人問：您憑什麼知道這一點呢？客商回答說：衛國國君崇尚儒術道德，禮賢下士尊重人才；衛國大臣竭盡節操效忠國家，面臨國家危難赴湯蹈火在所不辭。所以我深知國君英明而臣子忠誠。齊國人反問道：既然如此，那衛國為什麼依然如此弱小呢？客商回答說：衛國國土狹小、人口微薄，地處中原四面受敵。縱然擁有英明的君主與忠誠的大臣，但物質綜合國力根本不足以同周邊大國相抗衡，所以纔不可避免地處於弱勢地位。所謂地緣戰略客觀形勢力量，絕非單純依靠主觀道德品格就能強行扭轉控制的啊！\",\"analysis\":\"【篇旨與勢非德之所能制地緣政治客觀規律】通過齊衛客商問答，深刻破除「只要君明臣忠國家必強」的唯道德論迷信，確立「綜合國力、地緣板塊、戰略形勢（勢）」決定國家力量的客觀唯物主義地緣政治學。\\\\n【詞義訓詁】「客於齊」：寄居、遊學於齊國；「勢者非德之所能制」：客觀物質力量與地緣縱深非單純道德說教所能替代。\\\\n【現實主義國際關係】揭示小國在強國林立環境中的地緣困境，告誡國家治理必須建立在堅實的實體經濟與綜合國力之上。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-1_p-14\",\"chapterId\":\"liezi_ch-1\",\"order\":14,\"canonicalText\":\"楚人有擔山雉者，路人問曰：「何鳥也？」楚人誑之曰：「鳳凰也。」路人曰：「天下真鳳凰乎？我聞鳳凰見則天下安，今得見之，願以十金買之。」楚人曰：「不可。」請加至百金，乃與之。路人捧之而趨，欲獻於楚王。行未及半，雉死。路人不勝惋惜，市人皆悲其志。楚王聞之，感其欲獻己也，召而厚賜之，過於百金之數。故善欺者得利，好名者受賜，而天下莫悟其非鳳凰也。\",\"sentenceIds\":[\"liezi_ch-1_p-14_s-1\",\"liezi_ch-1_p-14_s-2\",\"liezi_ch-1_p-14_s-3\",\"liezi_ch-1_p-14_s-4\",\"liezi_ch-1_p-14_s-5\",\"liezi_ch-1_p-14_s-6\",\"liezi_ch-1_p-14_s-7\",\"liezi_ch-1_p-14_s-8\",\"liezi_ch-1_p-14_s-9\",\"liezi_ch-1_p-14_s-10\",\"liezi_ch-1_p-14_s-11\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"楚國有一個肩挑著山野野雞（山雉）進城販賣的人，路上的行人看見這隻羽毛漂亮的鳥便問道：這是什麼鳥啊？楚國人欺騙誆騙他說：這是神鳥鳳凰！路人驚喜地說：這真是天底下的真鳳凰嗎？我聽說鳳凰一旦現世天下就會太平安寧，今天有幸親眼目睹，我願意出十金的高價買下它。楚國人故意推辭說：十金太少，不賣。路人請求一路加價直到一百金，楚國人才把野雞賣給了他。路人無比恭敬地雙手捧著這隻野雞一路奔跑，準備將它進獻給楚王求取功名。然而剛走到半路上，野雞就死掉了。路人痛惜惋惜得不能自已，街市上的行人都為他的赤誠之志感到無比同情悲傷。楚王聽聞了這件事後，深深被他一心想將祥瑞進獻給自己的忠心所感動，特地召見他並賞賜給他巨額財富，賞賜的金額甚至遠遠超過了一百金的本錢！所以善於搞欺詐的人中飽私囊大獲橫財，貪圖虛名祥瑞的買鳥人與楚王大獲世俗讚賞恩賜，而全天下竟然沒有一個人清醒醒悟那根本就不是什麼鳳凰，而只是一隻普普通通的死野雞罷了！\",\"analysis\":\"【篇旨與楚人賣雉為鳳祥瑞政治與欺詐狂歡諷刺】極具辛辣諷刺意味之經典政治寓言——揭露從「奸商造假 → 愚民投機 → 昏君受騙獎賞 → 全社會沉淪」的「偽祥瑞產業鏈」，深刻批判封建統治者的好大喜功與社會集體盲從。\\\\n【詞義訓詁】「誑之」：誑，音逛，欺瞞訛騙；「過於百金之數」：楚王沉迷祥瑞被欺騙卻重賞投機者；「莫悟其非鳳凰」：全社會集體理性喪失。\\\\n【社會批判】揭露形式主義、政治投機與虛假政績如何通過制度漏洞獲取暴利，警示社會必須堅持求真務實。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-1_p-15\",\"chapterId\":\"liezi_ch-1\",\"order\":15,\"canonicalText\":\"天瑞篇終。子列子曰：「天地之大，萬物之多，皆生於無，歸於無。死生終始，莫非自然。達於天瑞者，不以生為榮，不以死為戚。順天之經，因地之義，安時處順，與道同體，此天瑞之極也。」\",\"sentenceIds\":[\"liezi_ch-1_p-15_s-1\",\"liezi_ch-1_p-15_s-2\",\"liezi_ch-1_p-15_s-3\",\"liezi_ch-1_p-15_s-4\",\"liezi_ch-1_p-15_s-5\",\"liezi_ch-1_p-15_s-6\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"〈天瑞〉篇總結。列子說：宇宙天地的浩瀚廣大，世間萬物的紛繁繁雜，全都是在大道無形中生成誕生，最終又全都回歸於無形本體。生命的誕生與死亡、萬事的開端與終結，無一不是大自然造化的客觀自然演進。真正通達領悟上天祥瑞造化（天瑞）真諦的人，絕不因為活在世上就沾沾自喜引以為榮，也絕不因為面臨死亡就悲傷哀慼恐懼痛苦。順應上天運轉的永恆常道，契合大地承載的自然情義，安於當下時節境遇而順應客觀變化，使自身的精神與永恆大道融為同一本體，這才是上天賜予生命最神聖極致的祥瑞真諦啊！\",\"analysis\":\"【篇旨與天瑞卷終大道至理安時處順天人同體】〈天瑞〉終篇總綱——重新定義「天瑞」非世俗神怪祥瑞，而是天地生生不息、自生自化、死生自然的客觀宇宙規律；達到「不以生為榮、不以死為戚、與道同體」方為人生最高境界。\\\\n【詞義訓詁】「天瑞」：上天自然造化之神妙祥和本質；「安時處順」：安於時運變化、心無掛礙；「與道同體」：天人合一之至高自由境。\\\\n【全篇哲學昇華】全篇從宇宙生成、天地分工、生死安息、杞人憂天至天瑞終極定義，構建了先秦道家無神論、唯物自然觀與豁達人生觀之宏偉大廈。\",\"historicalContext\":\"\",\"keywords\":[]}}],\"sentences\":[{\"id\":\"liezi_ch-1_p-1_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-1\",\"order\":1,\"canonicalText\":\"子列子居鄭圃，四十年人無識者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-1_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-1\",\"order\":2,\"canonicalText\":\"將國先後並事之，國人皆以列子為神仙。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-1_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-1\",\"order\":3,\"canonicalText\":\"列子居鄭圃，四十年人無識者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-1_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-1\",\"order\":4,\"canonicalText\":\"國君卿大夫視之，猶眾庶也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-1_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-1\",\"order\":5,\"canonicalText\":\"國不足，將往衛。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-1_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-1\",\"order\":6,\"canonicalText\":\"弟子曰：「先生往無反期，弟子敢有所問；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-1_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-1\",\"order\":7,\"canonicalText\":\"先生奚以教？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-1_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-1\",\"order\":8,\"canonicalText\":\"先生不聞壺丘子林之言乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-1_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-1\",\"order\":9,\"canonicalText\":\"」子列子曰：「壺丘子何言哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-1_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-1\",\"order\":10,\"canonicalText\":\"雖然，夫子嘗語伯昏瞀人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-1_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-1\",\"order\":11,\"canonicalText\":\"吾側聞之，試以告女。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-1_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-1\",\"order\":12,\"canonicalText\":\"其言曰：有生不生，有化不化。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-1_s-13\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-1\",\"order\":13,\"canonicalText\":\"不生者能生生，不化者能化化。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-1_s-14\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-1\",\"order\":14,\"canonicalText\":\"生者不能不生，化者不能不化，故常生常化。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-1_s-15\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-1\",\"order\":15,\"canonicalText\":\"常生常化者，無時不生，無時不化。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-1_s-16\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-1\",\"order\":16,\"canonicalText\":\"陰陽爾，四時爾，不生者疑獨，不化者往復。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-1_s-17\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-1\",\"order\":17,\"canonicalText\":\"往復，其際不可終；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-1_s-18\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-1\",\"order\":18,\"canonicalText\":\"疑獨，其道不可窮。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-1_s-19\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-1\",\"order\":19,\"canonicalText\":\"《黃帝書》曰：『穀神不死，是謂玄牝。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-1_s-20\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-1\",\"order\":20,\"canonicalText\":\"玄牝之門，是謂天地之根。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-1_s-21\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-1\",\"order\":21,\"canonicalText\":\"綿綿若存，用之不勤。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-1_s-22\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-1\",\"order\":22,\"canonicalText\":\"』故生物者不生，化物者不化。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-1_s-23\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-1\",\"order\":23,\"canonicalText\":\"自生自化，自形自色，自智自力，自消自息。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-1_s-24\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-1\",\"order\":24,\"canonicalText\":\"謂之生化形色智力消息者，非也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-1_s-25\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-1\",\"order\":25,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-2_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-2\",\"order\":1,\"canonicalText\":\"子列子曰：「昔者聖人因陰陽以統天地。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-2_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-2\",\"order\":2,\"canonicalText\":\"夫有形者生於無形，則天地安從生？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-2_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-2\",\"order\":3,\"canonicalText\":\"故曰：有太易，有太初，有太始，有太素。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-2_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-2\",\"order\":4,\"canonicalText\":\"太易者，未見氣也：太初者，氣之始也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-2_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-2\",\"order\":5,\"canonicalText\":\"太始者，形之始也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-2_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-2\",\"order\":6,\"canonicalText\":\"太素者，質之始也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-2_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-2\",\"order\":7,\"canonicalText\":\"氣形質具而未相離，故曰渾淪。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-2_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-2\",\"order\":8,\"canonicalText\":\"渾淪者，言萬物相渾淪而未相離也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-2_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-2\",\"order\":9,\"canonicalText\":\"視之不見，聽之不聞，循之不得，故曰易也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-2_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-2\",\"order\":10,\"canonicalText\":\"易無形埒，易變而為一，一變而為七，七變而為九。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-2_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-2\",\"order\":11,\"canonicalText\":\"九變者，窮也，乃復變而為一。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-2_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-2\",\"order\":12,\"canonicalText\":\"一者，形變之始也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-2_s-13\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-2\",\"order\":13,\"canonicalText\":\"清輕者上為天，濁重者下為地，沖和氣者為人；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-2_s-14\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-2\",\"order\":14,\"canonicalText\":\"故天地含精，萬物化生。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-2_s-15\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-2\",\"order\":15,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-3_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-3\",\"order\":1,\"canonicalText\":\"子列子曰：「天地無全功，聖人無全能，萬物無全用。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-3_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-3\",\"order\":2,\"canonicalText\":\"故天職生覆，地職形載，聖職教化，物職所宜。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-3_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-3\",\"order\":3,\"canonicalText\":\"然則天有所短，地有所長，聖有所窮，物有所通。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-3_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-3\",\"order\":4,\"canonicalText\":\"何則？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-3_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-3\",\"order\":5,\"canonicalText\":\"生覆者不能形載，形載者不能教化，教化者不能違所宜，宜定者不出所位。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-3_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-3\",\"order\":6,\"canonicalText\":\"故天地之道，非陰則陽；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-3_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-3\",\"order\":7,\"canonicalText\":\"聖人之教，非仁則義；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-3_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-3\",\"order\":8,\"canonicalText\":\"萬物之宜，非柔則剛：此皆隨所宜而不能出其位者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-3_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-3\",\"order\":9,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-4_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-4\",\"order\":1,\"canonicalText\":\"故有生者，有生生者；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-4_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-4\",\"order\":2,\"canonicalText\":\"有形者，有形形者；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-4_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-4\",\"order\":3,\"canonicalText\":\"有聲者，有聲聲者；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-4_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-4\",\"order\":4,\"canonicalText\":\"有色者，有色色者；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-4_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-4\",\"order\":5,\"canonicalText\":\"有味者，有味味者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-4_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-4\",\"order\":6,\"canonicalText\":\"生之所生者死矣，而生生者未嘗終；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-4_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-4\",\"order\":7,\"canonicalText\":\"形之所形者實矣，而形形者未嘗有；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-4_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-4\",\"order\":8,\"canonicalText\":\"聲之所聲者聞矣，而聲聲者未嘗發；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-4_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-4\",\"order\":9,\"canonicalText\":\"色之所色者彰矣，而色色者未嘗顯；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-4_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-4\",\"order\":10,\"canonicalText\":\"味之所味者嘗矣，而味味者未嘗呈。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-4_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-4\",\"order\":11,\"canonicalText\":\"皆道之為也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-5_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-5\",\"order\":1,\"canonicalText\":\"林類年且百歲，底春被裘，拾遺穗於故畦，並歌並行。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-5_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-5\",\"order\":2,\"canonicalText\":\"孔子適衛，望之於野。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-5_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-5\",\"order\":3,\"canonicalText\":\"顧謂弟子曰：「彼叟可與言者，試往訊之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-5_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-5\",\"order\":4,\"canonicalText\":\"」子貢請行。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-5_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-5\",\"order\":5,\"canonicalText\":\"逆之壟端，面之而歎曰：「先生曾不悔乎，而翡歌拾穗？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-5_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-5\",\"order\":6,\"canonicalText\":\"」林類行不返，歌不輟。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-5_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-5\",\"order\":7,\"canonicalText\":\"子貢遂躡而詰之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-5_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-5\",\"order\":8,\"canonicalText\":\"林類仰而應曰：「吾何悔邪？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-5_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-5\",\"order\":9,\"canonicalText\":\"」子貢曰：「先生少不勤行，長不競時，老無妻子，死期將至，亦有何樂而拾穗歌乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-5_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-5\",\"order\":10,\"canonicalText\":\"」林類笑曰：「吾之所以為樂，人皆有之，而反以為憂。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-5_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-5\",\"order\":11,\"canonicalText\":\"少不勤行，長不競時，故能遂算至今。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-5_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-5\",\"order\":12,\"canonicalText\":\"老無妻子，死期將至，故能歡樂。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-5_s-13\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-5\",\"order\":13,\"canonicalText\":\"孔子聞之，曰：「吾知其可與言，果然；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-5_s-14\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-5\",\"order\":14,\"canonicalText\":\"然特得其一，未得其二者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-5_s-15\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-5\",\"order\":15,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-6_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-6\",\"order\":1,\"canonicalText\":\"子貢倦於學，告仲尼曰：「願有所息。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-6_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-6\",\"order\":2,\"canonicalText\":\"」仲尼曰：「生無所息。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-6_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-6\",\"order\":3,\"canonicalText\":\"」子貢曰：「然則賜息無所乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-6_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-6\",\"order\":4,\"canonicalText\":\"」仲尼曰：「有焉耳。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-6_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-6\",\"order\":5,\"canonicalText\":\"望其壙，睪如也，填如也，鬲如也，枯如也，則知所息矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-6_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-6\",\"order\":6,\"canonicalText\":\"」子貢曰：「大哉死乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-6_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-6\",\"order\":7,\"canonicalText\":\"君子息焉，小人伏焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-6_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-6\",\"order\":8,\"canonicalText\":\"」仲尼曰：「賜！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-6_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-6\",\"order\":9,\"canonicalText\":\"汝知之矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-6_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-6\",\"order\":10,\"canonicalText\":\"人胥知生之樂，未知生之苦；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-6_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-6\",\"order\":11,\"canonicalText\":\"知老之憊，未知老之佚；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-6_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-6\",\"order\":12,\"canonicalText\":\"知死之惡，未知死之息也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-6_s-13\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-6\",\"order\":13,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-7_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-7\",\"order\":1,\"canonicalText\":\"晏子曰：「善哉，古之有死也！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-7_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-7\",\"order\":2,\"canonicalText\":\"仁者息焉，不仁者伏焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-7_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-7\",\"order\":3,\"canonicalText\":\"」死也者，德之徼也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-7_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-7\",\"order\":4,\"canonicalText\":\"古者謂死人為「歸人」，夫言死人為「歸人」，則生人為「行人」矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-7_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-7\",\"order\":5,\"canonicalText\":\"行而不知歸，失家者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-7_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-7\",\"order\":6,\"canonicalText\":\"一人失家，一世非之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-7_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-7\",\"order\":7,\"canonicalText\":\"天下失家，莫知非也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-7_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-7\",\"order\":8,\"canonicalText\":\"有人去鄉土、離六親、廢家業、遊於四方而不歸者，何人哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-7_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-7\",\"order\":9,\"canonicalText\":\"世必謂之狂蕩之人矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-7_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-7\",\"order\":10,\"canonicalText\":\"又有人鍾規矩、備節制、謀官祿、爭功名、終身馳騖而不返者，何人哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-7_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-7\",\"order\":11,\"canonicalText\":\"世必謂之智謀之士矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-7_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-7\",\"order\":12,\"canonicalText\":\"此二者，皆失家也，而世或笑之，或貴之，未知其俱惑也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-8_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-8\",\"order\":1,\"canonicalText\":\"杞國有人憂天地崩墜，身亡所寄，廢寢食者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-8_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-8\",\"order\":2,\"canonicalText\":\"又有憂彼之所憂者，因往曉之，曰：「天，積氣耳，亡處亡氣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-8_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-8\",\"order\":3,\"canonicalText\":\"若屈伸呼吸，終日在天中行止，奈何憂崩墜乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-8_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-8\",\"order\":4,\"canonicalText\":\"」其人曰：「天果積氣，日月星宿，不當墜耶？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-8_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-8\",\"order\":5,\"canonicalText\":\"」曉之者曰：「日月星宿，亦積氣中之有光耀者，只使墜，亦不能有所中傷。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-8_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-8\",\"order\":6,\"canonicalText\":\"」其人曰：「奈地壞何？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-8_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-8\",\"order\":7,\"canonicalText\":\"」曉之者曰：「地，積塊耳，充塞四虛，亡處亡塊。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-8_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-8\",\"order\":8,\"canonicalText\":\"若躇步跐蹈，終日在地上行止，奈何憂其壞？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-8_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-8\",\"order\":9,\"canonicalText\":\"」其人舍然大喜，曉之者亦舍然大喜。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-8_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-8\",\"order\":10,\"canonicalText\":\"長廬子聞而笑之曰：「虹蜺也，雲霧也，風雨也，四時也，此積氣之成乎天者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-8_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-8\",\"order\":11,\"canonicalText\":\"山嶽也，河海也，金石也，火木也，此積形之成乎地者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-8_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-8\",\"order\":12,\"canonicalText\":\"知積氣也，知積塊也，奚謂不壞？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-8_s-13\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-8\",\"order\":13,\"canonicalText\":\"夫天地，空中之一細物，有中之最巨者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-8_s-14\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-8\",\"order\":14,\"canonicalText\":\"難終難窮，此固然矣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-8_s-15\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-8\",\"order\":15,\"canonicalText\":\"難測難識，此固然矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-8_s-16\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-8\",\"order\":16,\"canonicalText\":\"憂其壞者，誠為大遠；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-8_s-17\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-8\",\"order\":17,\"canonicalText\":\"言其不壞者，亦未為是也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-8_s-18\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-8\",\"order\":18,\"canonicalText\":\"天地不得不壞，則會壞。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-8_s-19\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-8\",\"order\":19,\"canonicalText\":\"遇其壞時，奚為不憂哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-8_s-20\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-8\",\"order\":20,\"canonicalText\":\"」子列子聞而笑曰：「言天地壞者亦謬，言天地不壞者亦謬。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-8_s-21\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-8\",\"order\":21,\"canonicalText\":\"壞與不壞，吾所不能知也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-8_s-22\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-8\",\"order\":22,\"canonicalText\":\"雖然，彼一也，此一也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-8_s-23\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-8\",\"order\":23,\"canonicalText\":\"故生不知死，死不知生；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-8_s-24\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-8\",\"order\":24,\"canonicalText\":\"來不知往，往不知來。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-8_s-25\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-8\",\"order\":25,\"canonicalText\":\"壞與不壞，吾何容心哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-8_s-26\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-8\",\"order\":26,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-9_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-9\",\"order\":1,\"canonicalText\":\"舜問乎烝曰：「道可得而有乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-9_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-9\",\"order\":2,\"canonicalText\":\"」曰：「汝身非汝有也，汝何得有夫道？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-9_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-9\",\"order\":3,\"canonicalText\":\"」舜曰：「吾身非吾有也，孰有之哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-9_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-9\",\"order\":4,\"canonicalText\":\"」曰：「是天地之委形也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-9_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-9\",\"order\":5,\"canonicalText\":\"生非汝有，是天地之委和也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-9_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-9\",\"order\":6,\"canonicalText\":\"性命非汝有，是天地之委順也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-9_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-9\",\"order\":7,\"canonicalText\":\"孫子非汝有，是天地之委蛻也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-9_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-9\",\"order\":8,\"canonicalText\":\"故行不知所往，處不知所持，食不知所味。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-9_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-9\",\"order\":9,\"canonicalText\":\"天地之強陽氣也，又胡可得而有邪？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-9_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-9\",\"order\":10,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-10_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-10\",\"order\":1,\"canonicalText\":\"齊之國氏大富，宋之向氏大貧。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-10_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-10\",\"order\":2,\"canonicalText\":\"向氏之齊，請其術。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-10_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-10\",\"order\":3,\"canonicalText\":\"國氏告之曰：「吾善為盜。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-10_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-10\",\"order\":4,\"canonicalText\":\"始吾為盜也，一年而給，二年而足，三年大穰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-10_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-10\",\"order\":5,\"canonicalText\":\"自此以往，施及州閭。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-10_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-10\",\"order\":6,\"canonicalText\":\"」向氏大喜，徒聞其言，不達其理。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-10_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-10\",\"order\":7,\"canonicalText\":\"乃逾垣鑿室，手妄掇，目妄指，無所不取。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-10_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-10\",\"order\":8,\"canonicalText\":\"未及時，以贓獲罪，沒其先居之產。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-10_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-10\",\"order\":9,\"canonicalText\":\"向氏以為國氏之詒己也，往而怨之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-10_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-10\",\"order\":10,\"canonicalText\":\"國氏曰：「若為盜若何？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-10_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-10\",\"order\":11,\"canonicalText\":\"」向氏言其狀。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-10_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-10\",\"order\":12,\"canonicalText\":\"國氏曰：「嘻！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-10_s-13\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-10\",\"order\":13,\"canonicalText\":\"若失為盜之道至此乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-10_s-14\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-10\",\"order\":14,\"canonicalText\":\"請更語若：吾聞天有時，地有利。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-10_s-15\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-10\",\"order\":15,\"canonicalText\":\"吾盜天地之時利，雲雨之滂沛，山澤之產育，以生吾禾，殖吾稼，築吾垣，建吾舍。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-10_s-16\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-10\",\"order\":16,\"canonicalText\":\"陸盜禽獸，水盜魚鱉，亡非盜也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-10_s-17\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-10\",\"order\":17,\"canonicalText\":\"夫禾稼、土木、禽獸、魚鱉，皆天之所生，豈吾之所有？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-10_s-18\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-10\",\"order\":18,\"canonicalText\":\"然吾盜天而亡殃。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-10_s-19\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-10\",\"order\":19,\"canonicalText\":\"若盜人之金玉珠帛，穀粟貨財，獲罪於人，非天也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-10_s-20\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-10\",\"order\":20,\"canonicalText\":\"若不知天地之公，而奪人之私，何怨於吾？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-10_s-21\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-10\",\"order\":21,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-11_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-11\",\"order\":1,\"canonicalText\":\"燕丹子曰：「田光先生，燕國之勇士也，智深而勇沈，可與謀大事。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-11_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-11\",\"order\":2,\"canonicalText\":\"」太子丹私見田光，曰：「燕、秦不兩立，願先生留意。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-11_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-11\",\"order\":3,\"canonicalText\":\"」田光曰：「臣聞騏驥盛壯之時，一日千里；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-11_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-11\",\"order\":4,\"canonicalText\":\"至其衰老，駑馬先之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-11_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-11\",\"order\":5,\"canonicalText\":\"今太子聞光盛壯之時，不知臣精已消亡矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-11_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-11\",\"order\":6,\"canonicalText\":\"雖然，光不敢以乏國事也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-11_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-11\",\"order\":7,\"canonicalText\":\"所善荊軻，可使也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-11_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-11\",\"order\":8,\"canonicalText\":\"」太子曰：「願因先生得交於荊軻。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-11_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-11\",\"order\":9,\"canonicalText\":\"」田光曰：「敬諾。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-11_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-11\",\"order\":10,\"canonicalText\":\"」退而見荊軻，語之曰：「光與子相善，燕國莫不知。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-11_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-11\",\"order\":11,\"canonicalText\":\"今太子聞光盛壯之時，不知吾形已不逮也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-11_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-11\",\"order\":12,\"canonicalText\":\"幸而語曰：『燕、秦不兩立，願先生留意。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-11_s-13\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-11\",\"order\":13,\"canonicalText\":\"』光竊不自外，言足下於太子，願足下過太子於宮。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-11_s-14\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-11\",\"order\":14,\"canonicalText\":\"」荊軻曰：「謹奉教。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-11_s-15\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-11\",\"order\":15,\"canonicalText\":\"」田光曰：「吾聞長者之行，不使人疑之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-11_s-16\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-11\",\"order\":16,\"canonicalText\":\"今太子告光曰：『所言者，國之大事，願先生勿泄。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-11_s-17\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-11\",\"order\":17,\"canonicalText\":\"』是太子疑光也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-11_s-18\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-11\",\"order\":18,\"canonicalText\":\"夫為行而使人疑之，非節俠也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-11_s-19\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-11\",\"order\":19,\"canonicalText\":\"」遂自殺以厲荊軻。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-12_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-12\",\"order\":1,\"canonicalText\":\"孔子兼三才之道，六藝之業，弟子三千，身通六藝者七十有二人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-12_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-12\",\"order\":2,\"canonicalText\":\"遊於宋，匡人圍之數匝，歌鼓琴聲不絕。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-12_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-12\",\"order\":3,\"canonicalText\":\"子路入見，曰：「何夫子之娛也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-12_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-12\",\"order\":4,\"canonicalText\":\"」孔子曰：「由，來！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-12_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-12\",\"order\":5,\"canonicalText\":\"吾語汝。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-12_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-12\",\"order\":6,\"canonicalText\":\"吾諱窮久矣，而不免，命也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-12_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-12\",\"order\":7,\"canonicalText\":\"求通久矣，而不得，時也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-12_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-12\",\"order\":8,\"canonicalText\":\"當文王既沒，文不在茲乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-12_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-12\",\"order\":9,\"canonicalText\":\"天之將喪斯文也，後死者不得與於斯文也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-12_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-12\",\"order\":10,\"canonicalText\":\"天之未喪斯文也，匡人其如予何？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-12_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-12\",\"order\":11,\"canonicalText\":\"夫水行不避蛟龍者，漁父之勇也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-12_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-12\",\"order\":12,\"canonicalText\":\"陸行不避兕虎者，獵夫之勇也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-12_s-13\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-12\",\"order\":13,\"canonicalText\":\"白刃交於前，視死若生者，烈士之勇也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-12_s-14\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-12\",\"order\":14,\"canonicalText\":\"知窮之有命，知通之有時，臨大難而不懼者，聖人之勇也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-12_s-15\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-12\",\"order\":15,\"canonicalText\":\"由，處矣！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-12_s-16\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-12\",\"order\":16,\"canonicalText\":\"吾命有所制矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-12_s-17\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-12\",\"order\":17,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-13_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-13\",\"order\":1,\"canonicalText\":\"衛人有客於齊者，齊人有問之曰：「衛之君臣何如？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-13_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-13\",\"order\":2,\"canonicalText\":\"」客曰：「君明臣忠。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-13_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-13\",\"order\":3,\"canonicalText\":\"」齊人曰：「何以知之？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-13_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-13\",\"order\":4,\"canonicalText\":\"」客曰：「其君好儒，禮賢下士；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-13_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-13\",\"order\":5,\"canonicalText\":\"其臣盡節，死難不避。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-13_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-13\",\"order\":6,\"canonicalText\":\"故知其明且忠也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-13_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-13\",\"order\":7,\"canonicalText\":\"」齊人曰：「然則衛何以弱？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-13_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-13\",\"order\":8,\"canonicalText\":\"」客曰：「國小地狹，四面受敵。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-13_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-13\",\"order\":9,\"canonicalText\":\"雖有明君忠臣，力不足以抗大國，故弱也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-13_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-13\",\"order\":10,\"canonicalText\":\"夫勢者，非德之所能制也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-13_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-13\",\"order\":11,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-14_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-14\",\"order\":1,\"canonicalText\":\"楚人有擔山雉者，路人問曰：「何鳥也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-14_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-14\",\"order\":2,\"canonicalText\":\"」楚人誑之曰：「鳳凰也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-14_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-14\",\"order\":3,\"canonicalText\":\"」路人曰：「天下真鳳凰乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-14_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-14\",\"order\":4,\"canonicalText\":\"我聞鳳凰見則天下安，今得見之，願以十金買之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-14_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-14\",\"order\":5,\"canonicalText\":\"」楚人曰：「不可。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-14_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-14\",\"order\":6,\"canonicalText\":\"」請加至百金，乃與之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-14_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-14\",\"order\":7,\"canonicalText\":\"路人捧之而趨，欲獻於楚王。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-14_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-14\",\"order\":8,\"canonicalText\":\"行未及半，雉死。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-14_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-14\",\"order\":9,\"canonicalText\":\"路人不勝惋惜，市人皆悲其志。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-14_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-14\",\"order\":10,\"canonicalText\":\"楚王聞之，感其欲獻己也，召而厚賜之，過於百金之數。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-14_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-14\",\"order\":11,\"canonicalText\":\"故善欺者得利，好名者受賜，而天下莫悟其非鳳凰也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-15_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-15\",\"order\":1,\"canonicalText\":\"天瑞篇終。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-15_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-15\",\"order\":2,\"canonicalText\":\"子列子曰：「天地之大，萬物之多，皆生於無，歸於無。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-15_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-15\",\"order\":3,\"canonicalText\":\"死生終始，莫非自然。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-15_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-15\",\"order\":4,\"canonicalText\":\"達於天瑞者，不以生為榮，不以死為戚。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-15_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-15\",\"order\":5,\"canonicalText\":\"順天之經，因地之義，安時處順，與道同體，此天瑞之極也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-1_p-15_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-1\",\"passageId\":\"liezi_ch-1_p-15\",\"order\":6,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]}]}") as ChapterBundle
